class WebuiTimeShiftResultsError(Exception):
    """
    Raised when Time Shift of WebUI results is not correct.
    """
    pass


class L3CallMeasurementsError(Exception):
    """
    Raised when cell info for RMOD could not be found.
    """
    pass


class MissingMeasurementError(Exception):
    """
    Raised when required type of measurement is not in results.
    """
    pass
